      if(Number.isFinite(daily)&&daily>0)artist.dailySpotifyStreams=daily;
      if(monthlyOk&&Number.isFinite(monthly)&&monthly>0){artist.monthlyListeners=monthly;artist.monthlyListenersLastUpdatedAt=verifiedAt;}
